changeSet.sql:
DO $$
DECLARE
    violation_count BIGINT;
    sample_rows TEXT;
BEGIN
    WITH violations AS (
        SELECT format('company_document id=%s tenant_id=%s references file_storage id=%s tenant_id=%s',
                      document.id, document.tenant_id, file.id, file.tenant_id) AS detail
        FROM "${schema}".company_document AS document
        JOIN "${schema}".file_storage AS file ON file.id = document.file_storage_id
        WHERE document.tenant_id <> file.tenant_id
    ), samples AS (
        SELECT detail FROM violations ORDER BY detail LIMIT 10
    )
    SELECT (SELECT COUNT(*) FROM violations),
           (SELECT string_agg(detail, E'\n') FROM samples)
    INTO violation_count, sample_rows;
    IF violation_count > 0 THEN
        RAISE EXCEPTION 'File-upload stage migration blocked: % company document/file tenant mismatch(es) exist.', violation_count
            USING DETAIL = sample_rows,
                  HINT = 'Correct each listed company_document tenant_id or file_storage relationship without deleting document history, then rerun the tenant migration.';
    END IF;
END;
$$;

ALTER TABLE "${schema}".file_upload_stage ADD CONSTRAINT chk_file_upload_stage_purpose CHECK (purpose IN ('COMPANY_DOCUMENT')), ADD CONSTRAINT chk_file_upload_stage_expiry CHECK (expires_at > created_at), ADD CONSTRAINT chk_file_upload_stage_claim CHECK ((claimed_at IS NULL) = (claimed_resource_id IS NULL));
CREATE INDEX idx_file_upload_stage_unclaimed ON "${schema}".file_upload_stage (tenant_id, purpose, created_by, expires_at) WHERE claimed_at IS NULL;
CREATE TRIGGER trg_file_upload_stage_updated_at BEFORE UPDATE ON "${schema}".file_upload_stage FOR EACH ROW EXECUTE FUNCTION kabipay_ops.set_updated_at();

rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM "${schema}".file_upload_stage) THEN
        RAISE EXCEPTION 'Cannot roll back file-upload staging while stage rows exist.'
            USING HINT = 'Claim every valid stage, or remove each unclaimed stage and its matching file_storage record/object through the supported company-upload cleanup operation. Then rerun rollback.';
    END IF;
END;
$$;

ALTER TABLE "${schema}".company_document DROP CONSTRAINT IF EXISTS fk_company_document_file_tenant;
ALTER TABLE "${schema}".company_document
    ADD CONSTRAINT fk_company_document_file
    FOREIGN KEY (file_storage_id) REFERENCES "${schema}".file_storage (id)
    ON DELETE RESTRICT;
ALTER TABLE "${schema}"."user" DROP CONSTRAINT IF EXISTS uq_user_id_tenant;
ALTER TABLE "${schema}".company_document DROP CONSTRAINT IF EXISTS uq_company_document_id_tenant;
